<div id="supplier-modal" class="fixed inset-0 z-[100] hidden items-center justify-center bg-black/40 p-4"><div class="absolute inset-0" onclick="closeSupplierModal()"></div><div class="relative w-full max-w-2xl rounded-xl bg-white shadow-2xl"><div class="flex justify-between border-b border-outline-variant px-6 py-4"><h2 id="supplier-title" class="text-xl font-semibold">Tambah Supplier Baru</h2><button type="button" onclick="closeSupplierModal()"><span class="material-symbols-outlined">close</span></button></div><form id="supplier-form" method="POST" action="<?php echo e(route('master-supplier.store')); ?>" class="space-y-4 p-6"><?php echo csrf_field(); ?><div><label class="mb-1 block font-semibold">Kode Supplier</label><input value="[otomatis]" readonly class="w-full rounded-md border border-outline-variant bg-surface-container-low px-3 py-2 text-on-surface-variant"></div><div><label class="mb-1 block font-semibold">Nama Supplier *</label><input id="supplier-nama" name="nm_master_supplier" required class="w-full rounded-md border border-outline-variant px-3 py-2"></div><div><label class="mb-1 block font-semibold">Alamat *</label><textarea id="supplier-alamat" name="alamat_supplier" rows="3" required class="w-full rounded-md border border-outline-variant px-3 py-2"></textarea></div><div><label class="mb-1 block font-semibold">Kontak *</label><input id="supplier-kontak" name="kontak_supplier" inputmode="numeric" required class="w-full rounded-md border border-outline-variant px-3 py-2"></div><div><label class="mb-1 block font-semibold">Status *</label><select id="supplier-status" name="status_master_supplier" required class="w-full rounded-md border border-outline-variant px-3 py-2"><option>AKTIF</option><option>TIDAK AKTIF</option></select></div><div class="flex justify-end gap-2 border-t border-outline-variant pt-4"><button type="button" onclick="closeSupplierModal()" class="rounded-md border px-4 py-2">Batal</button><button class="rounded-md bg-primary px-5 py-2 font-label-bold text-on-primary">Simpan Supplier</button></div></form></div></div><script>function openSupplierModal(){const m=document.getElementById('supplier-modal');m.classList.remove('hidden');m.classList.add('flex');document.getElementById('supplier-title').textContent='Tambah Supplier Baru';document.getElementById('supplier-form').action='<?php echo e(route('master-supplier.store')); ?>';document.getElementById('supplier-form').querySelector('[name="_method"]')?.remove()}function closeSupplierModal(){const m=document.getElementById('supplier-modal');m.classList.add('hidden');m.classList.remove('flex')}function editSupplier(id,n,a,k,s){openSupplierModal();document.getElementById('supplier-title').textContent='Edit Supplier';document.getElementById('supplier-form').action='<?php echo e(url('/master-supplier')); ?>/'+id;let m=document.getElementById('supplier-form').querySelector('[name="_method"]');if(!m){m=document.createElement('input');m.type='hidden';m.name='_method';document.getElementById('supplier-form').prepend(m)}m.value='PUT';document.getElementById('supplier-nama').value=n||'';document.getElementById('supplier-alamat').value=a||'';document.getElementById('supplier-kontak').value=k||'';document.getElementById('supplier-status').value=s||'AKTIF'}</script><?php /**PATH D:\ProjectPDAM\laragon-6.0-minimal\www\MasterData_FULL_FIXED\MasterData\resources\views/components/master/supplier/modal.blade.php ENDPATH**/ ?>